package hu.laci.cms.backend.dao.content;
import hu.laci.cms.backend.dao.common.BaseDao; import hu.laci.cms.backend.model.common.QuerySpec; import hu.laci.cms.backend.model.content.*; import hu.laci.cms.backend.model.site.Site; import java.util.*;
/** JDBC tag persistence. */ public class TagDaoImpl extends BaseDao<Tag,TagProperty> implements TagDao { public TagDaoImpl(){super(Tag.class);} public List<Tag> findBySite(Site s){return findAll(QuerySpec.<TagProperty>create().where(TagProperty.SITE).equalsTo(s).orderBy(TagProperty.CODE.asc()));} public Optional<Tag> findBySiteAndId(Site s,Long id){return findAll(QuerySpec.<TagProperty>create().where(TagProperty.SITE).equalsTo(s).where(TagProperty.ID).equalsTo(id)).stream().findFirst();} public Optional<Tag> findBySiteAndCode(Site s,String c){return findAll(QuerySpec.<TagProperty>create().where(TagProperty.SITE).equalsTo(s).where(TagProperty.CODE).equalsTo(c)).stream().findFirst();} public long countContentItems(Tag t){return findCustomOne("countTagUsage","SELECT COUNT(*) AS row_count FROM content_item_tags WHERE tag_id = ?",List.of(t),r->r.getLong("row_count"),"Failed to count tag usage.").orElse(0L);} public void deleteUnusedBySite(Site s){executeCustomUpdate("deleteUnusedTags","DELETE FROM tags t WHERE t.site_id = ? AND NOT EXISTS (SELECT 1 FROM content_item_tags cit WHERE cit.tag_id=t.id)",List.of(s),"Failed to delete unused tags.");} }
